{
  "name": "ACQ400 数据流客户端",
  "name_en": "ACQ400 Stream Client",
  "manufacturer": "",
  "description": "用于连接 ACQ400/ACQ2106 系列采集系统的主机端软件客户端，负责实时数据流读取、状态监视、通道数据获取、校准换算以及采集相关服务配置。它用于实验中的高速数据采集与后处理，本身不是实体仪器。",
  "description_en": "A host-side software client for connecting to ACQ400/ACQ2106 acquisition systems. It handles live data streaming, status monitoring, channel data retrieval, calibration-based scaling, and acquisition-related service configuration. It is used for high-speed experimental data capture and post-processing, and is not a physical instrument itself.",
  "tag_hints": [
    "ACQ400",
    "DAQ streaming",
    "status monitoring",
    "post-shot data retrieval",
    "channel scaling",
    "synchronization routing",
    "pattern generator loading"
  ],
  "actions": [
    {
      "action_name": "read",
      "description": "读取实时流或原始数据。",
      "description_en": "Read live stream or raw data."
    },
    {
      "action_name": "get_blocks",
      "description": "获取数据块。",
      "description_en": "Get data blocks."
    },
    {
      "action_name": "st_monitor",
      "description": "监视状态通道。",
      "description_en": "Monitor the status channel."
    },
    {
      "action_name": "get_state",
      "description": "获取当前采集状态。",
      "description_en": "Get the current acquisition state."
    },
    {
      "action_name": "get_pre",
      "description": "获取预触发样本数。",
      "description_en": "Get the pre-trigger sample count."
    },
    {
      "action_name": "get_post",
      "description": "获取后触发样本数。",
      "description_en": "Get the post-trigger sample count."
    },
    {
      "action_name": "get_total",
      "description": "获取总样本数。",
      "description_en": "Get the total sample count."
    },
    {
      "action_name": "get_elapsed",
      "description": "获取已采集样本数。",
      "description_en": "Get the elapsed sample count."
    },
    {
      "action_name": "wait_event",
      "description": "等待状态或系统事件。",
      "description_en": "Wait for a status or system event."
    },
    {
      "action_name": "wait_armed",
      "description": "等待系统进入就绪状态。",
      "description_en": "Wait for the system to become armed."
    },
    {
      "action_name": "wait_stopped",
      "description": "等待采集停止。",
      "description_en": "Wait for acquisition to stop."
    },
    {
      "action_name": "wait_state_changed",
      "description": "等待状态变化。",
      "description_en": "Wait for a state change."
    },
    {
      "action_name": "init_site_client",
      "description": "初始化站点客户端连接。",
      "description_en": "Initialize a site client connection."
    },
    {
      "action_name": "make_sa_sd_aliases",
      "description": "创建站点别名映射。",
      "description_en": "Create site alias mappings."
    },
    {
      "action_name": "get_sys_info",
      "description": "获取系统信息。",
      "description_en": "Get system information."
    },
    {
      "action_name": "close",
      "description": "关闭客户端连接。",
      "description_en": "Close the client connection."
    },
    {
      "action_name": "state",
      "description": "查询当前状态。",
      "description_en": "Query the current state."
    },
    {
      "action_name": "post_samples",
      "description": "获取后触发样本数。",
      "description_en": "Get the post-trigger sample count."
    },
    {
      "action_name": "pre_samples",
      "description": "获取预触发样本数。",
      "description_en": "Get the pre-trigger sample count."
    },
    {
      "action_name": "elapsed_samples",
      "description": "获取已采集样本数。",
      "description_en": "Get the elapsed sample count."
    },
    {
      "action_name": "demux_status",
      "description": "获取解复用状态。",
      "description_en": "Get demultiplexing status."
    },
    {
      "action_name": "samples",
      "description": "获取样本计数信息。",
      "description_en": "Get sample count information."
    },
    {
      "action_name": "get_aggregator_sites",
      "description": "获取聚合器站点列表。",
      "description_en": "Get the list of aggregator sites."
    },
    {
      "action_name": "get_aggregator_svc_list",
      "description": "获取聚合器服务列表。",
      "description_en": "Get the aggregator service list."
    },
    {
      "action_name": "fetch_all_calibration",
      "description": "获取全部校准数据。",
      "description_en": "Fetch all calibration data."
    },
    {
      "action_name": "scale_raw",
      "description": "按校准参数缩放原始数据。",
      "description_en": "Scale raw data using calibration parameters."
    },
    {
      "action_name": "chan2volts",
      "description": "将通道原始数据换算为电压。",
      "description_en": "Convert channel raw data to volts."
    },
    {
      "action_name": "read_chan",
      "description": "读取单个通道的数据。",
      "description_en": "Read data from a single channel."
    },
    {
      "action_name": "read_decims",
      "description": "读取抽取后的数据。",
      "description_en": "Read decimated data."
    },
    {
      "action_name": "nchan",
      "description": "获取通道数量。",
      "description_en": "Get the number of channels."
    },
    {
      "action_name": "data_size",
      "description": "获取数据大小。",
      "description_en": "Get the data size."
    },
    {
      "action_name": "uut_demux_enabled",
      "description": "查询设备端是否启用解复用。",
      "description_en": "Query whether device-side demultiplexing is enabled."
    },
    {
      "action_name": "read_transient_timebase",
      "description": "读取瞬态采集时间基。",
      "description_en": "Read the transient acquisition timebase."
    },
    {
      "action_name": "load_segments",
      "description": "加载分段采集配置。",
      "description_en": "Load segmented acquisition configuration."
    },
    {
      "action_name": "show_segments",
      "description": "显示分段配置信息。",
      "description_en": "Show segmented configuration information."
    },
    {
      "action_name": "clear_counters",
      "description": "清除计数器。",
      "description_en": "Clear counters."
    },
    {
      "action_name": "set_sync_routing_master",
      "description": "设置主设备同步路由。",
      "description_en": "Set synchronization routing for the master device."
    },
    {
      "action_name": "set_sync_routing_slave",
      "description": "设置从设备同步路由。",
      "description_en": "Set synchronization routing for the slave device."
    },
    {
      "action_name": "set_sync_routing",
      "description": "设置同步路由。",
      "description_en": "Set synchronization routing."
    },
    {
      "action_name": "set_mb_clk",
      "description": "设置主背板时钟。",
      "description_en": "Set the main backplane clock."
    },
    {
      "action_name": "load_stl",
      "description": "加载 STL 配置或序列表。",
      "description_en": "Load STL configuration or sequence data."
    },
    {
      "action_name": "load_gpg",
      "description": "加载通用脉冲发生器配置。",
      "description_en": "Load general-purpose pulse generator configuration."
    },
    {
      "action_name": "load_dpg",
      "description": "加载数字脉冲发生器配置。",
      "description_en": "Load digital pulse generator configuration."
    },
    {
      "action_name": "load_wrpg",
      "description": "加载 WRPG 配置。",
      "description_en": "Load WRPG configuration."
    },
    {
      "action_name": "load_dio482pg",
      "description": "加载 DIO482 脉冲发生器配置。",
      "description_en": "Load DIO482 pulse generator configuration."
    },
    {
      "action_name": "set_DO",
      "description": "设置数字输出状态。",
      "description_en": "Set the digital output state."
    },
    {
      "action_name": "load_awg",
      "description": "加载任意波形发生器数据。",
      "description_en": "Load arbitrary waveform generator data."
    },
    {
      "action_name": "set_segment",
      "description": "设置当前采集分段参数。",
      "description_en": "Set current acquisition segment parameters."
    },
    {
      "action_name": "run_service",
      "description": "运行指定服务。",
      "description_en": "Run a specified service."
    }
  ]
}

